{"command": "python3 << 'EOF'
from docx import Document
import math

doc = Document('/work/output/NovaTrans_Board_Decision_Brief.docx')

# page estimate: Letter 8.5x11, margins 0.55/0.65 -> usable 7.2" x 9.9" (712pt)
usable_w_px = 7.2 * 96
page_pt = 712.0
total_pt = 0.0

def lines_px(text, px_per_char):
    if not text.strip():
        return 1
    n = 0
    for seg in text.split('\n'):
        n += max(1, math.ceil(len(seg) * px_per_char / usable_w_px))
    return n

for p in doc.paragraphs:
    sz = 9.5
    for r in p.runs:
        if r.font.size:
            sz = r.font.size.pt
            break
    pitch = sz * 1.15 + 3
    total_pt += lines_px(p.text, 0.64 * sz) * pitch

for t in doc.tables:
    for row in t.rows:
        row_lines = 1
        for c in row.cells:
            w_in = (c.width.inches if c.width else 1.0)
            wpx = w_in * 96 - 8
            run_sz = 8.0
            for p in c.paragraphs:
                for r in p.runs:
                    if r.font.size:
                        run_sz = r.font.size.pt
                        break
            ppc = 0.64 * run_sz
            n = max(1, math.ceil(len(c.text) * ppc / max(wpx, 20)))
            row_lines = max(row_lines, n)
        total_pt += row_lines * (8 * 1.15 + 4)

print('paragraphs:', len(doc.paragraphs), 'tables:', len(doc.tables))
print('estimated content height:', round(total_pt), 'pt =', round(total_pt / page_pt, 2), 'pages')

print('\n===== FULL TEXT DUMP =====\n')
for p in doc.paragraphs:
    if p.text.strip():
        print('P:', p.text)
for ti, t in enumerate(doc.tables):
    print(f'\n--- TABLE {ti + 1} ---')
    for row in t.rows:
        print(' | '.join(c.text for c in row.cells))
EOF", "description": "Estimate page count and dump brief content"}

